"""The native ``create_branch`` tool for Copilot v2.

Moves the run onto a new branch of the agent, so the turn's edits and its
end-of-run commit land there instead of on the branch the run started on. Only
offered to runs whose client opted into branching.
"""

from __future__ import annotations

from pydantic_ai import Agent, ModelRetry, RunContext
from pydantic_ai.tools import ToolDefinition

from rasa.builder.copilot.constants import TOOL_CREATE_BRANCH
from rasa.builder.copilot.pydantic_ai.run_context import CopilotRunContext
from rasa.builder.copilot.pydantic_ai.workspace import BranchOffError

# Each refusal is a tool retry, and pydantic-ai ends the run once a tool has
# failed more often than this.
_BRANCH_TOOL_RETRIES = 3

_BRANCH_TOOL_DESCRIPTION = (
    "Create a git branch from the current branch and work in it for the rest of "
    "the turn. The name is short kebab-case describing the change, for example "
    "'add-returns-flow'. Call it before editing any file."
)


def register_branch_tool(agent: Agent[CopilotRunContext, str]) -> None:
    """Register the native ``create_branch`` tool on the agent.

    The tool switches ``ctx.deps.workspace`` to the new branch and repoints
    ``ctx.deps.project_path`` at its checkout, so every later file tool call and
    the end-of-run commit act on the new branch.
    """

    @agent.tool(
        name=TOOL_CREATE_BRANCH,
        description=_BRANCH_TOOL_DESCRIPTION,
        retries=_BRANCH_TOOL_RETRIES,
        prepare=_offer_when_branching,
    )
    async def create_branch(
        ctx: RunContext[CopilotRunContext],
        name: str,
    ) -> dict[str, str]:
        """Create a branch from the current one, switch to it, and report both."""
        workspace = ctx.deps.workspace
        if workspace is None:
            raise ModelRetry("Branching is not available in this session.")
        if ctx.deps.made_changes:
            raise ModelRetry(
                "Files were already edited on the current branch. Create the "
                "branch before editing files; keep working on this branch."
            )
        base = workspace.branch
        try:
            branch = await workspace.branch_off(name)
        except BranchOffError as exc:
            raise ModelRetry(str(exc)) from exc
        ctx.deps.project_path = str(workspace.path)
        return {"branch": branch, "base": base}


async def _offer_when_branching(
    ctx: RunContext[CopilotRunContext], tool_def: ToolDefinition
) -> ToolDefinition | None:
    """Offer the tool only to runs whose client opted into branching."""
    return tool_def if ctx.deps.workspace is not None else None
